Given a 2D array intervals[][], where intervals[i] = [starti, endi]. Find the minimum number of intervals need to be removed to make the rest of the intervals non-overlapping.Note: Two intervals are considered non-overlapping if the end time of one interval is less than or equal to the start time of the next interval.Examples:Input: intervals[][] = [[1, 2], [2, 3], [3, 4], [1, 3]]Output: 1 Explanation: Removal of [1, 3] makes the ranges non-overlapping. Input: intervals[][] = [[1, 3], [1, 3], [1, 3]]Output: 2 Explanation: Removal of two occurrences of [1, 3] makes the remaining ranges non-overlapping. Input: intervals[][]  = [[1, 2], [5, 10], [18, 35], [40, 45]] Output: 0 Explanation: All ranges are already non-overlapping.Try It YourselfTable of ContentSorting by the Starting Values - O(n log n) Time and O(1) SpaceSorting by the Ending Values - O(n log n) Time and O(1) SpaceSorting by the Starting Values - O(n log n) Time and O(1) SpaceThe idea is to use a greedy approach to select the interval to be removed, such that removal count is minimized. First we sort the intervals by their starting values. Then traverse through the interval array and check if any interval has a starting point smaller than the ending point of the previous interval (ie. there is an overlap). In case overlapping occurs remove the interval with greater ending point.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int minRemoval(vector<vector<int>>& intervals) {
  	int cnt = 0;

    // Sort by minimum starting point
    sort(intervals.begin(), intervals.end());

    int end = intervals[0][1];
    for (int i = 1; i < intervals.size(); i++) {

        // If the current starting point is less than
        // the previous interval's ending point
        // (ie. there is an overlap)
        if (intervals[i][0] < end) {

            // Increase cnt and remove the interval
            // with the higher ending point
          	cnt++;
            end = min(intervals[i][1], end);
        }

      	// Incase of no overlapping, this interval is 
      	// not removed and 'end' will be updated
        else
            end = intervals[i][1];
    }

    return cnt;
}

int main() {
    vector<vector<int> > intervals = {{1, 2}, {2, 3}, {3, 4}, {1, 3}};
    cout << minRemoval(intervals) << endl;
}


